:host {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #00CED1;
  --warm: #FFBF00;
  --line: #bdc3c7;
  --paper: #f9f9f9;
  --bg: #ffffff;
  --font-main: "Georgia", serif;
  --font-mono: "Consolas", monospace;
}

.chapter-container {
  font-family: var(--font-main);
  color: var(--ink);
  background: var(--bg);
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  line-height: 1.6;
}

.chapter-header {
  border-bottom: 2px solid var(--ink);
  margin-bottom: 2rem;
  padding-bottom: 1rem;
}

.section-title {
  font-size: 1.8rem;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
}

.section-takeaway {
  font-size: 1.1rem;
  color: var(--muted);
  font-style: italic;
  margin: 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 2rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.column-logic, .column-visual {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.logic-block, .final-solution-block {
  background: var(--paper);
  padding: 1.5rem;
  border-left: 4px solid var(--accent);
  border-radius: 4px;
}

.block-title {
  font-size: 1.2rem;
  margin-top: 0;
  margin-bottom: 0.8rem;
  color: var(--ink);
}

.text-body {
  font-size: 1rem;
  margin-bottom: 1rem;
  color: var(--ink);
}

.formula-box {
  background: #fff;
  border: 1px solid var(--line);
  padding: 1rem;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 1.1rem;
  margin: 1rem 0;
  position: relative;
}

.formula-box.large {
  font-size: 1.3rem;
  background: #fff;
  border: 2px solid var(--accent);
}

.formula-note {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 0.5rem;
  font-family: var(--font-main);
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.2rem 0.6rem;
  font-size: 0.8rem;
  cursor: pointer;
  border-radius: 3px;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--ink);
  color: var(--ink);
}

.viz-panel {
  background: var(--paper);
  padding: 1.5rem;
  border-radius: 4px;
  border: 1px solid var(--line);
}

.viz-header {
  margin-bottom: 1rem;
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
  justify-content: space-between;
}

.viz-header h3 {
  width: 100%;
  margin: 0 0 0.5rem 0;
  font-size: 1.1rem;
}

.control-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9rem;
}

.control-group label {
  font-weight: bold;
}

.value-display {
  font-family: var(--font-mono);
  min-width: 3rem;
  text-align: right;
}

.action-btn, .reset-btn {
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 3px;
  cursor: pointer;
  font-weight: bold;
  font-size: 0.9rem;
}

.action-btn {
  background: var(--accent);
  color: #fff;
}

.action-btn:hover {
  opacity: 0.9;
}

.reset-btn {
  background: var(--line);
  color: var(--ink);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  height: 400px;
  background: #fff;
  border: 1px solid var(--line);
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.canvas-overlay {
  position: absolute;
  top: 1rem;
  right: 1rem;
  pointer-events: none;
}

.data-panel {
  background: rgba(255, 255, 255, 0.9);
  padding: 0.8rem;
  border: 1px solid var(--line);
  font-size: 0.85rem;
  font-family: var(--font-mono);
}

.data-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.3rem;
}

.caption-note {
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 0.8rem;
  font-style: italic;
}

.limitations-section {
  margin-top: 2rem;
  padding: 1.5rem;
  background: #fff8e1;
  border-left: 4px solid var(--warm);
  border-radius: 4px;
}

.limit-list {
  margin: 0.5rem 0 0 1.5rem;
  padding: 0;
  font-size: 0.95rem;
}

.limit-list li {
  margin-bottom: 0.5rem;
  color: var(--ink);
}

javascript:
(function() {
  const canvas = document.getElementById('estimator-canvas');
  const ctx = canvas.getContext('2d');
  const slider = document.getElementById('error-slider');
  const errorVal = document.getElementById('error-val');
  const applyBtn = document.getElementById('apply-correction');
  const resetBtn = document.getElementById('reset-viz');
  const traceInitEl = document.getElementById('trace-init');
  const traceFinalEl = document.getElementById('trace-final');
  const biasShiftEl = document.getElementById('bias-shift');

  // 教学参数：真值位置 (相对于画布中心)
  const TRUE_X = 0;
  const TRUE_Y = 0;
  const SCALE = 3; // 像素缩放比例

  // 状态
  let state = {
    step1Error: 0.3, // 0-1
    corrected: false,
    step1Center: { x: 20, y: -15 }, // 初始偏差
    step1Cov: [[100, 10], [10, 80]], // 初始协方差
    step2Cov: [[20, 2], [2, 15]] // 修正后协方差 (教学值)
  };

  function drawEllipse(ctx, center, cov, color, lineWidth, fill) {
    // 特征值分解计算椭圆轴
    const a = cov[0][0];
    const b = cov[0][1];
    const d = cov[1][1];
    const trace = a + d;
    const det = a * d - b * b;
    const discriminant = Math.sqrt(trace * trace - 4 * det);

    const lambda1 = (trace + discriminant) / 2;
    const lambda2 = (trace - discriminant) / 2;

    const majorAxis = Math.sqrt(lambda1) * SCALE * 2.15; // 95% 置信区间 ~2.15 sigma
    const minorAxis = Math.sqrt(lambda2) * SCALE * 2.15;

    let angle = 0;
    if (Math.abs(b) > 1e-6) {
      angle = 0.5 * Math.atan2(2 * b, a - d);
    }

    ctx.save();
    ctx.translate(center.x * SCALE + canvas.width / 2, -center.y * SCALE + canvas.height / 2);
    ctx.rotate(-angle); // Canvas Y 轴向下，需反转旋转

    ctx.beginPath();
    ctx.ellipse(0, 0, majorAxis, minorAxis, 0, 0, 2 * Math.PI);

    if (fill) {
      ctx.fillStyle = color + '33'; // 20% 透明度
      ctx.fill();
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
    ctx.restore();
  }

  function drawGrid() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = '#e0e0e0';
    ctx.lineWidth = 1;

    // 绘制网格
    const step = 50;
    for (let x = 0; x <= canvas.width; x += step) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, canvas.height);
      ctx.stroke();
    }
    for (let y = 0; y <= canvas.height; y += step) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvas.width, y);
      ctx.stroke();
    }

    // 绘制坐标轴
    ctx.strokeStyle = '#bdc3c7';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(canvas.width / 2, 0);
    ctx.lineTo(canvas.width / 2, canvas.height);
    ctx.moveTo(0, canvas.height / 2);
    ctx.lineTo(canvas.width, canvas.height / 2);
    ctx.stroke();

    // 绘制真值
    ctx.fillStyle = '#FF4500';
    ctx.beginPath();
    ctx.arc(canvas.width / 2 + TRUE_X * SCALE, canvas.height / 2 - TRUE_Y * SCALE, 5, 0, 2 * Math.PI);
    ctx.fill();
    ctx.fillStyle = '#2c3e50';
    ctx.font = '12px Consolas';
    ctx.fillText('真值 (True)', canvas.width / 2 + 10, canvas.height / 2 - 10);
  }

  function updateDisplay() {
    // 计算协方差迹 (Trace) 作为误差度量
    const trace1 = state.step1Cov[0][0] + state.step1Cov[1][1];
    const trace2 = state.step2Cov[0][0] + state.step2Cov[1][1];

    // 偏差距离
    const biasDist = Math.sqrt(state.step1Center.x ** 2 + state.step1Center.y ** 2);

    traceInitEl.textContent = trace1.toFixed(2);
    if (state.corrected) {
      traceFinalEl.textContent = trace2.toFixed(2);
      biasShiftEl.textContent = '已修正 (≈0)';
      biasShiftEl.style.color = '#00CED1';
    } else {
      traceFinalEl.textContent = '--';
      biasShiftEl.textContent = biasDist.toFixed(1) + ' px';
      biasShiftEl.style.color = '#FF4500';
    }
  }

  function render() {
    drawGrid();

    // 根据滑块调整第一步误差椭圆大小
    const errorFactor = 0.5 + state.step1Error * 1.5;
    const currentCov = [
      [state.step1Cov[0][0] * errorFactor, state.step1Cov[0][1] * errorFactor],
      [state.step1Cov[1][0] * errorFactor, state.step1Cov[1][1] * errorFactor]
    ];

    // 绘制第一步解 (青色)
    drawEllipse(ctx, state.step1Center, currentCov, '#00CED1', 2, true);
    ctx.fillStyle = '#00CED1';
    ctx.beginPath();
    ctx.arc(state.step1Center.x * SCALE + canvas.width / 2, -state.step1Center.y * SCALE + canvas.height / 2, 4, 0, 2 * Math.PI);
    ctx.fill();
    ctx.fillText('第一步解 (Step 1)', state.step1Center.x * SCALE + canvas.width / 2 + 10, -state.step1Center.y * SCALE + canvas.height / 2 - 10);

    // 如果已修正，绘制第二步解 (琥珀色/绿色)
    if (state.corrected) {
      // 修正后中心趋近真值，添加微小随机扰动模拟残差
      const residual = { x: (Math.random() - 0.5) * 2, y: (Math.random() - 0.5) * 2 };
      const finalCenter = { x: TRUE_X + residual.x, y: TRUE_Y + residual.y };

      drawEllipse(ctx, finalCenter, state.step2Cov, '#2E8B57', 2, true);
      ctx.fillStyle = '#2E8B57';
      ctx.beginPath();
      ctx.arc(finalCenter.x * SCALE + canvas.width / 2, -finalCenter.y * SCALE + canvas.height / 2, 4, 0, 2 * Math.PI);
      ctx.fill();
      ctx.fillText('第二步解 (Step 2)', finalCenter.x * SCALE + canvas.width / 2 + 10, -finalCenter.y * SCALE + canvas.height / 2 - 10);
    }

    updateDisplay();
  }

  // 事件监听
  slider.addEventListener('input', (e) => {
    state.step1Error = parseInt(e.target.value, 10) / 100;
    errorVal.textContent = e.target.value + '%';
    state.corrected = false; // 重置修正状态
    render();
  });

  applyBtn.addEventListener('click', () => {
    state.corrected = true;
    render();
  });

  resetBtn.addEventListener('click', () => {
    state.step1Error = 0.3;
    slider.value = 30;
    errorVal.textContent = '30%';
    state.corrected = false;
    render();
  });

  // 初始化
  render();
})();
